result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/gridgen/src/generate.ts", "content": "/**
 * Responsive grid stylesheet generator.
 *
 * Emits:
 *   .row            -> flexbox row container with gutter compensation
 *   .col-1..N       -> percentage column widths (4 decimal places)
 *   .bp\:col-1..N   -> same widths inside min-width media queries
 */

export interface GridOptions {
  columns?: number;
  gutter?: string;
  breakpoints?: Record<string, number>;
}

export interface GridConfig {
  columns: number;
  gutter: string;
  breakpoints: Record<string, number>;
}

const DEFAULTS: Required<GridOptions> = {
  columns: 12,
  gutter: '1rem',
  breakpoints: { sm: 640, md: 768, lg: 1024 },
};

/** Percentage width for a span, fixed to exactly 4 decimal places. */
export function widthFor(span: number, columns = DEFAULTS.columns): string {
  return `${((span / columns) * 100).toFixed(4)}%`;
}

/**
 * Class name helper.
 *   classFor(5)        -> 'col-5'
 *   classFor(5, 'md')  -> 'md\\:col-5'  (CSS-escaped colon)
 */
export function classFor(span: number, breakpoint?: string): string {
  if (!Number.isInteger(span) || span < 1) {
    throw new RangeError(`span must be a positive integer, got ${span}`);
  }
  const base = `col-${span}`;
  return breakpoint ? `${breakpoint}\\:${base}` : base;
}

function colRule(span: number, config: GridConfig): string {
  return `.${classFor(span)} { width: ${widthFor(span, config.columns)}; }`;
}

function mediaBlock(bp: string, px: number, config: GridConfig): string {
  const inner = Array.from({ length: config.columns }, (_, i) => {
    const span = i + 1;
    return `  .${classFor(span, bp)} { width: ${widthFor(span, config.columns)}; }`;
  }).join('\n');
  return `@media (min-width: ${px}px) {\n${inner}\n}`;
}

export function makeGrid(options: GridOptions = {}): string {
  const config: GridConfig = {
    columns: options.columns ?? DEFAULTS.columns,
    gutter: options.gutter ?? DEFAULTS.gutter,
    breakpoints: options.breakpoints ?? DEFAULTS.breakpoints,
  };
  const { columns, gutter } = config;

  if (!Number.isInteger(columns) || columns < 1) {
    throw new RangeError(`columns must be a positive integer, got ${columns}`);
  }

  const halfGutter = `calc(${gutter} / 2)`;

  const lines: string[] = [
    `* { box-sizing: border-box; }`,
    ``,
    `.row {`,
    `  display: flex;`,
    `  flex-wrap: wrap;`,
    `  margin-left: calc(${halfGutter} * -1);`,
    `  margin-right: calc(${halfGutter} * -1);`,
    `}`,
    ``,
    `.row > [class*="col"] {`,
    `  padding-left: ${halfGutter};`,
    `  padding-right: ${halfGutter};`,
    `}`,
    ``,
  ];

  for (let span = 1; span <= columns; span++) {
    lines.push(colRule(span, config));
  }

  for (const [bp, px] of Object.entries(config.breakpoints)) {
    lines.push('', mediaBlock(bp, px, config));
  }

  return lines.join('\n') + '\n';
}
"})
