result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/gridgen/test/generate.test.ts", "content": "import { describe, it, expect } from 'vitest';
import postcss from 'postcss';

import { makeGrid, classFor, widthFor } from '../src/generate';

const css = makeGrid({ columns: 12, gutter: '1rem', breakpoints: { sm: 640, md: 768, lg: 1024 } });

describe('classFor', () => {
  it('maps base spans without breakpoint', () => {
    expect(classFor(1)).toBe('col-1');
    expect(classFor(5)).toBe('col-5');
    expect(classFor(12)).toBe('col-12');
  });

  it('escapes the colon for breakpoint variants', () => {
    expect(classFor(3, 'sm')).toBe('sm\\:col-3');
    expect(classFor(8, 'lg')).toBe('lg\\:col-8');
  });

  it('rejects invalid spans', () => {
    expect(() => classFor(0)).toThrow(RangeError);
    expect(() => classFor(-2)).toThrow(RangeError);
    expect(() => classFor(1.5)).toThrow(RangeError);
  });

  it('widthFor fixes to 4 decimal places', () => {
    expect(widthFor(1)).toBe('8.3333%');
    expect(widthFor(5)).toBe('41.6667%');
    expect(widthFor(12)).toBe('100.0000%');
  });
});

describe('emitted CSS', () => {
  const root = postcss.parse(css);

  const rules = root.nodes.filter((n) => n.type === 'rule');

  const selectorOf = (r: postcss.Rule) => r.selector.replace(/\s+/g, ' ').trim();

  it('.row uses flexbox', () => {
    const row = root.nodes.find(
      (n) => n.type === 'rule' && selectorOf(n as postcss.Rule) === '.row',
    ) as postcss.Rule;
    expect(row).toBeDefined();
    expect(row.propValueOrThrow === undefined || true).toBeTruthy(); // placeholder guard
    expect(row.nodes.map((d) => `${(d as postcss.Declaration).prop}: ${(d as postcss.Declaration).value}`))
      .toContain('display: flex');
    expect(row.nodes.some((d) => (d as postcss.Declaration).prop === 'flex-wrap')).toBe(true);
  });

  it('col-5 width is 41.6667%', () => {
    const col5 = rules.find((r) => selectorOf(r) === '.col-5')!;
    expect(col5).toBeDefined();
    const width = col5.nodes.find((d) => (d as postcss.Declaration).prop === 'width') as postcss.Declaration;
    expect(width.value).toBe('41.6667%');
  });

  it('each breakpoint has exactly 12 rules in the right media query params', () => {
    const expected: Record<string, number> = { sm: 640, md: 768, lg: 1024 };
    for (const [bp, px] of Object.entries(expected)) {
      const media = root.nodes.filter((n) => n.type === 'atrule' && (n as postcss.AtRule).name === 'media'
        && (n as postcss.AtRule).params === `(min-width: ${px}px)`);
      expect(media).toHaveLength(1);

      const innerRules = media[0].nodes!.filter((n) => n.type === 'rule');
      expect(innerRules).toHaveLength(12);

      for (let span = 1; span <= 12; span++) {
        expect(innerRules.some((r) => selectorOf(r as postcss.Rule) === classFor(span, bp))).toBe(true);
      }
    }
  });

  it('no duplicate selectors exist across the stylesheet', () => {
    const seen = new Map<string, number>();
    root.walkRules((rule) => {
      const key = `${rule.parent?.type === 'atrule' ? `@${(rule.parent as postcss.AtRule).params} | ` : ''}${selectorOf(rule)}`;
      seen.set(key, (seen.get(key) ?? 0) + 1);
    });
    const dupes = [...seen.entries()].filter(([, count]) => count > 1);
    expect(dupes).toEqual([]);
  });

  it('base columns are outside any media query and number 12', () => {
    const baseCols = rules.filter((r) => /^\.col-\d+$/.test(selectorOf(r)));
    expect(baseCols).toHaveLength(12);
    expect(baseCols.every((r) => r.parent!.type === 'root')).toBe(true);
  });
});
"})
